import { useDroppable } from "@dnd-kit/core";

import { cn } from "../../lib/cn";
import type { GroupEdgeDropData, PaneEdgeDropData, TabDropEdge } from "./tabDragTypes";

type SplitEdgeDropData = GroupEdgeDropData | PaneEdgeDropData;

type SplitEdgeDropZoneProps = {
  id: string;
  data: SplitEdgeDropData;
  edge: TabDropEdge;
  testId: string;
  groupId?: string;
  tabId?: string;
  leafId?: string;
};

/**
 * Shared split-edge target used by both tab drags and pane-handle drags.
 * Drag source only changes the command resolved after drop; target geometry and
 * visual feedback intentionally follow the same tab-drag contract.
 */
export function SplitEdgeDropZone({
  id,
  data,
  edge,
  testId,
  groupId,
  tabId,
  leafId,
}: SplitEdgeDropZoneProps) {
  const { setNodeRef, isOver } = useDroppable({ id, data });

  return (
    <>
      <div
        ref={setNodeRef}
        aria-hidden="true"
        data-testid={testId}
        data-split-edge-drop-zone="true"
        data-dnd-type={data.type}
        data-drop-edge={edge}
        data-drop-group-id={groupId}
        data-tab-id={tabId}
        data-leaf-id={leafId}
        className={cn(
          "pointer-events-none absolute z-40 transition-colors",
          edgeHitTargetClass(edge),
        )}
      />
      {isOver ? (
        <div
          aria-hidden="true"
          data-testid="split-edge-preview"
          data-split-edge-preview="true"
          data-preview-edge={edge}
          className={cn(
            "pointer-events-none absolute z-40 border-2 border-primary bg-primary/20 backdrop-blur-[1px] transition-colors",
            edgePreviewClass(edge),
          )}
        >
          <span
            data-testid="split-edge-drop-feedback"
            className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm"
          >
            New split
          </span>
        </div>
      ) : null}
    </>
  );
}

export function edgeHitTargetClass(edge: TabDropEdge): string {
  switch (edge) {
    case "left":
      return "inset-y-0 left-0 w-[20%]";
    case "right":
      return "inset-y-0 right-0 w-[20%]";
    case "top":
      return "left-[20%] right-[20%] top-0 h-[20%]";
    case "bottom":
      return "bottom-0 left-[20%] right-[20%] h-[20%]";
  }
}

function edgePreviewClass(edge: TabDropEdge): string {
  switch (edge) {
    case "left":
      return "inset-y-0 left-0 w-1/2";
    case "right":
      return "inset-y-0 right-0 w-1/2";
    case "top":
      return "inset-x-0 top-0 h-1/2";
    case "bottom":
      return "inset-x-0 bottom-0 h-1/2";
  }
}

import type { PaneDirection } from "../../state/paneTree";

export type TabDropEdge = "left" | "right" | "top" | "bottom";

export type TabDragData = {
  type: "tab";
  tabId: string;
  groupId: string;
  index: number;
};

export type PaneDragData = {
  type: "pane";
  tabId: string;
  sourcePaneId?: string;
  sourceSessionId?: string;
  leafId?: string;
};

export type GroupBodyDropData = {
  type: "group-body";
  groupId: string;
};

export type GroupEdgeDropData = {
  type: "group-edge";
  groupId: string;
  edge: TabDropEdge;
};

export type PaneLeafDropData = {
  type: "pane-leaf";
  tabId: string;
  leafId: string;
};

export type PaneEdgeDropData = {
  type: "pane-edge";
  tabId: string;
  leafId: string;
  edge: TabDropEdge;
};

export type WorkspaceDragData = TabDragData | PaneDragData;
export type WorkspaceDropData = TabDragData | GroupBodyDropData | GroupEdgeDropData | PaneLeafDropData | PaneEdgeDropData;

export type WorkspaceDropCommand =
  | {
      type: "move-tab-to-group";
      tabId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "move-tab-to-split";
      tabId: string;
      targetGroupId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "move-tab-to-pane-split";
      sourceTabId: string;
      targetTabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "move-pane-to-pane-split";
      sourceTabId: string;
      sourceLeafId: string;
      targetTabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "detach-pane-to-tab";
      sourceTabId: string;
      leafId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "swap-panes";
      tabId: string;
      sourceLeafId: string;
      targetLeafId: string;
    };

export function isWorkspaceDragData(value: unknown): value is WorkspaceDragData {
  if (!value || typeof value !== "object") return false;
  if (!("type" in value)) return false;
  const type = value.type;
  if (type === "tab") {
    return (
      "tabId" in value &&
      typeof value.tabId === "string" &&
      "groupId" in value &&
      typeof value.groupId === "string" &&
      "index" in value &&
      typeof value.index === "number"
    );
  }
  if (type === "pane") {
    return (
      "tabId" in value &&
      typeof value.tabId === "string" &&
      (("sourcePaneId" in value && typeof value.sourcePaneId === "string") ||
        ("leafId" in value && typeof value.leafId === "string"))
    );
  }
  return false;
}

export function isWorkspaceDropData(value: unknown): value is WorkspaceDropData {
  if (!value || typeof value !== "object") return false;
  if (!("type" in value)) return false;
  const type = value.type;
  switch (type) {
    case "tab":
      return (
        "tabId" in value &&
        typeof value.tabId === "string" &&
        "groupId" in value &&
        typeof value.groupId === "string" &&
        "index" in value &&
        typeof value.index === "number"
      );
    case "group-body":
      return "groupId" in value && typeof value.groupId === "string";
    case "group-edge":
      return "groupId" in value && typeof value.groupId === "string" && "edge" in value && isTabDropEdge(value.edge);
    case "pane-leaf":
      return "tabId" in value && typeof value.tabId === "string" && "leafId" in value && typeof value.leafId === "string";
    case "pane-edge":
      return (
        "tabId" in value &&
        typeof value.tabId === "string" &&
        "leafId" in value &&
        typeof value.leafId === "string" &&
        "edge" in value &&
        isTabDropEdge(value.edge)
      );
    default:
      return false;
  }
}

export function resolveWorkspaceDropCommand(
  active: WorkspaceDragData,
  over: WorkspaceDropData | null,
): WorkspaceDropCommand | null {
  if (!over) return null;

  if (active.type === "tab") {
    switch (over.type) {
      case "pane-edge": {
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-tab-to-pane-split",
          sourceTabId: active.tabId,
          targetTabId: over.tabId,
          targetLeafId: over.leafId,
          direction,
          position,
        };
      }
      case "group-edge": {
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-tab-to-split",
          tabId: active.tabId,
          targetGroupId: over.groupId,
          direction,
          position,
        };
      }
      case "tab":
        if (over.tabId === active.tabId && over.groupId === active.groupId) return null;
        return {
          type: "move-tab-to-group",
          tabId: active.tabId,
          targetGroupId: over.groupId,
          targetIndex: over.index,
        };
      case "group-body":
        return {
          type: "move-tab-to-group",
          tabId: active.tabId,
          targetGroupId: over.groupId,
        };
      case "pane-leaf":
        return null;
    }
  }

  if (active.type === "pane") {
    const sourceLeafId = active.sourcePaneId ?? active.leafId ?? "";
    switch (over.type) {
      case "pane-edge": {
        if (over.tabId === active.tabId && over.leafId === sourceLeafId) return null;
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-pane-to-pane-split",
          sourceTabId: active.tabId,
          sourceLeafId,
          targetTabId: over.tabId,
          targetLeafId: over.leafId,
          direction,
          position,
        };
      }
      case "tab":
        return {
          type: "detach-pane-to-tab",
          sourceTabId: active.tabId,
          leafId: sourceLeafId,
          targetGroupId: over.groupId,
          targetIndex: over.index + 1,
        };
      case "group-body":
        return {
          type: "detach-pane-to-tab",
          sourceTabId: active.tabId,
          leafId: sourceLeafId,
          targetGroupId: over.groupId,
        };
      case "pane-leaf":
        if (over.tabId !== active.tabId || over.leafId === sourceLeafId) return null;
        return {
          type: "swap-panes",
          tabId: active.tabId,
          sourceLeafId,
          targetLeafId: over.leafId,
        };
      case "group-edge":
        return null;
    }
  }

  return null;
}

export function dropPriority(active: WorkspaceDragData, over: WorkspaceDropData): number {
  if (active.type === "tab") {
    if (over.type === "pane-edge") return over.edge === "left" || over.edge === "right" ? 0 : 1;
    if (over.type === "group-edge") return over.edge === "left" || over.edge === "right" ? 2 : 3;
    if (over.type === "tab") return 4;
    if (over.type === "group-body") return 5;
    return 100;
  }

  if (over.type === "pane-edge") return over.edge === "left" || over.edge === "right" ? 0 : 1;
  if (over.type === "tab") return 2;
  if (over.type === "group-body") return 3;
  if (over.type === "pane-leaf") return 4;
  return 100;
}

export function edgeToSplit(edge: TabDropEdge): { direction: PaneDirection; position: "first" | "second" } {
  if (edge === "left") return { direction: "horizontal", position: "first" };
  if (edge === "right") return { direction: "horizontal", position: "second" };
  if (edge === "top") return { direction: "vertical", position: "first" };
  return { direction: "vertical", position: "second" };
}

function isTabDropEdge(value: unknown): value is TabDropEdge {
  return value === "left" || value === "right" || value === "top" || value === "bottom";
}

